import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const dataDir = join(__dirname, "..", "..", "data");
const outFile = join(__dirname, "..", "data.js");

const banner =
  "// Auto-generated by tools/build-data.js from /data/bills.json + /data/rewards.json.\n" +
  "// Do not edit by hand — run `npm run build:data` to regenerate.\n";

const bills = JSON.parse(readFileSync(join(dataDir, "bills.json"), "utf8"));
const rewards = JSON.parse(readFileSync(join(dataDir, "rewards.json"), "utf8"));

const body = `window.DATA = ${JSON.stringify({ bills, rewards }, null, 2)};\n`;
const output = banner + body;

const check = process.argv.includes("--check");
if (check) {
  const existing = existsSync(outFile) ? readFileSync(outFile, "utf8") : "";
  if (existing !== output) {
    console.error("web/data.js is out of date. Run `npm run build:data`.");
    process.exit(1);
  }
  console.log("web/data.js is up to date.");
} else {
  writeFileSync(outFile, output, "utf8");
  console.log(`Wrote web/data.js (${output.length} bytes) from /data/bills.json + /data/rewards.json`);
}
